<script>
(()=>{const list=document.getElementById('dashboardStackList'),form=document.getElementById('dashboardLayoutForm'),status=document.getElementById('layoutStatus');if(!list||!form)return;let dragging=null;const rows=()=>[...list.querySelectorAll('[data-stack-id]')];function move(row,direction){const items=rows(),i=items.indexOf(row),target=items[i+direction];if(!target)return;if(direction<0)list.insertBefore(row,target);else list.insertBefore(target,row)}rows().forEach(row=>{row.addEventListener('dragstart',event=>{dragging=row;row.classList.add('is-dragging');event.dataTransfer.effectAllowed='move'});row.addEventListener('dragend',()=>{row.classList.remove('is-dragging');dragging=null});row.addEventListener('dragover',event=>{if(!dragging||dragging===row)return;event.preventDefault();const r=row.getBoundingClientRect();list.insertBefore(dragging,event.clientY>r.top+r.height/2?row.nextSibling:row)});row.querySelectorAll('[data-move]').forEach(button=>button.addEventListener('click',()=>move(row,button.dataset.move==='up'?-1:1)))});form.addEventListener('submit',event=>{const checked=list.querySelectorAll('input[name="visible[]"]:checked');if(!checked.length){event.preventDefault();status.textContent='Keep at least one dashboard section visible.';status.style.color='#fb9c9c'}else status.textContent='Saving your default layout…'})})();
</script>
